import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
from rdkit import Chem
ls=open('answer.xyz').readlines()[2:];els=[l.split()[0] for l in ls];p=np.array([[float(k) for k in l.split()[1:]]for l in ls])
fig=plt.figure(figsize=(10,9));ax=fig.add_subplot(111,projection='3d')
cols={'C':'gray','H':'lightgray','N':'blue','O':'red','Ru':'purple','Cl':'green'}
for i,(el,pos) in enumerate(zip(els,p)):
 ax.scatter(*pos,c=cols[el],s=90 if el=='Ru' else 35 if el!='H' else 10)
 if el!='H': ax.text(*pos,str(i),size=8)
for mol,off in [(Chem.MolFromMolFile('ligand_final.mol',removeHs=False),2),(Chem.AddHs(Chem.MolFromSmiles('CC(C)c1ccc(C)cc1')),50)]:
 for b in mol.GetBonds():
  u,v=p[b.GetBeginAtomIdx()+off],p[b.GetEndAtomIdx()+off];ax.plot(*np.array([u,v]).T,c='black',alpha=.6,lw=1)
for i in [1,8,9,53,54,55,56,58,59]: ax.plot(*np.array([p[0],p[i]]).T,c='purple',alpha=.6,lw=1)
ax.set_box_aspect(np.ptp(p,axis=0));ax.view_init(elev=24,azim=-60)
plt.savefig('structure.png',dpi=140)
